  "welcomeGuidedTourStep": {
    "title": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Willkommen bei Baserow" } },
    "content": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Lassen Sie uns einen kurzen Rundgang machen, um Sie mit den Grundlagen vertraut zu machen. In nur wenigen Klicks lernen Sie, wie Sie Ihre Daten mühelos organisieren und visualisieren können" } },
    "buttonText": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Tour starten" } }
  },
  "controlCenterGuidedTourStep": {
    "title": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Ihre Baserow-Schaltzentrale" } },
    "content": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Die linke Seitenleiste hilft Ihnen, Ihren Arbeitsbereich zu verwalten:\n\n- Startseite – Greifen Sie auf Ihr Haupt-Dashboard zu.\n- Benachrichtigungen – Bleiben Sie über Änderungen und Erwähnungen informiert.\n- Mitglieder einladen – Arbeiten Sie zusammen, indem Sie Teammitglieder hinzufügen.\n- Papierkorb – Listen Sie alle gelöschten Elemente auf und stellen Sie sie wieder her." } }
  },
  "createNewGuidedTourStep": {
    "title": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Neue Datenbank oder Anwendung erstellen" } },
    "content": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Klicken Sie auf „Neu hinzufügen…“, um eine neue Datenbank, Anwendung oder ein neues Dashboard für Ihr Projekt, Ihre Abteilung oder Ihr Team einzurichten." } }
  },
  "mcpEndpointSettings": {
    "title": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "MCP-Server" } },
    "createEndpoint": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Endpunkt erstellen" } },
    "createNewTitle": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "MCP-Server-Endpunkt erstellen" } },
    "backToOverview": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Zurück" } },
    "noEndpointsMessage": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Es wurden keine MCP-Server-Endpunkte (Model Context Protocol) hinzugefügt. Diese können verwendet werden, um direkt mit einem LLM wie Claude zu integrieren und dem LLM zu erlauben, Aktionen direkt in Baserow auszuführen. Erstellen Sie einen Server-Endpunkt, um zu beginnen." } }
  },
  "mcpEndpointForm": {
    "nameLabel": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Name" } },
    "workspaceLabel": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Arbeitsbereich" } }
  },
  "mcpEndpoint": {
    "detailLabel": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Weitere Details" } },
    "endpointURLIntro": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Die MCP-Server-URL (Model Context Protocol) kann zu jedem Client hinzugefügt werden, der MCP-Server unterstützt. Es handelt sich um einen eindeutigen Endpunkt, der dem LLM in Ihrem Auftrag direkten Zugriff auf Aktionen im Arbeitsbereich gewährt." } },
    "reveal": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Vollständige URL anzeigen" } },
    "warning": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Behandeln Sie Ihre MCP-URL wie ein Passwort, da sie die Möglichkeit hat, Daten in Baserow zu ändern." } },
    "claudeInstructions": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Drei einfache Schritte, um mit Claude Desktop und dem Baserow MCP zu beginnen.\n\n1. Öffnen Sie die Claude Desktop-Einstellungen über die Navigationsleiste. (⌘+,)\n1. Wechseln Sie zur Registerkarte „Develop“ und klicken Sie auf „Edit Config“.\n1. Fügen Sie die folgende JSON-Konfiguration in `claude_desktop_config.json` ein." } },
    "cursorInstructions": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Drei einfache Schritte, um mit Cursor und dem Baserow MCP zu beginnen.\n\n1. Öffnen Sie die Cursor-Einstellungen (⇧+⌘+J)\n1. Navigieren Sie zur Registerkarte „MCP“ und klicken Sie auf „Add MCP Server“\n1. Fügen Sie die folgende JSON-Konfiguration hinzu." } },
    "windsurfInstructions": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Zwei einfache Schritte, um MCP mit Cascade in Windsurf einzurichten.\n\n1. Navigieren Sie zu Windsurf - Settings -> Advanced Settings oder Command Palette -> Open Windsurf settings page.\n1. Scrollen Sie nach unten zum Abschnitt Cascade. Dort finden Sie die Option, einen neuen Server hinzuzufügen, vorhandene Server anzuzeigen, und eine Schaltfläche, um die JSON-Konfigurationsdatei `mcp_config.json` direkt anzuzeigen. Fügen Sie das Folgende hinzu:" } }
  },
